function curry(fn) {
  return function curried(...args) {
    if (args.length >= fn.length) return fn(...args);
    return (...more) => curried(...args, ...more);
  };
}

const fee = curry((base, rate, extra = 0) => base * rate + extra);

console.log(fee(10)(2));
console.log(fee(10, 2, 5));
console.log(fee(10)(2, 5));
console.log(typeof fee(10));
